use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let cents = input.as_i64().unwrap();
    let pounds = cents as f64 / 2.20462;
    let pounds_rounded = pounds.round();
    let pounds_str = format!("{:.2}", pounds_rounded);
    let result = serde_json::Value::String(pounds_str);
    result
}

fn main() {
    let input = serde_json::Value::from("{\"input\":-1230,\"expected\":\"-12.30\"}");
    let output = solve(input);
    println!("{}", output);
}
```

This Rust code defines a function `solve` that takes a JSON input and returns a JSON output. The function converts the input cents to pounds, rounds the result to two decimal places, and formats it as a string. The `main` function demonstrates how to use the `solve` function with a sample input.
